CREATE FUNCTION public.apply_drive_record(p_binding uuid,p_file text,p_doc jsonb,p_site_version integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.drive_sync_bindings;r public.campaign_records; BEGIN SELECT * INTO b FROM public.drive_sync_bindings WHERE id=p_binding; IF NOT b.enabled OR NOT b.privacy_reviewed OR NOT b.runtime_authorized OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=b.confirmed_by AND role='admin') THEN RETURN false; END IF; IF NOT EXISTS(SELECT 1 FROM public.drive_sync_files WHERE binding_id=b.id AND file_id=p_file AND entity_type='record' AND entity_id=(p_doc->>'id')::uuid) THEN RETURN false; END IF; SELECT * INTO r FROM public.campaign_records WHERE id=(p_doc->>'id')::uuid FOR UPDATE; IF NOT FOUND OR r.version<>p_site_version OR r.visibility='gm' OR NOT ((b.scope='house' AND r.visibility='house' AND r.house_id=b.house_id AND p_doc->>'visibility'='house' AND p_doc->>'houseId'=r.house_id AND p_doc->>'playerId' IS NULL) OR (b.scope='player' AND r.visibility='player' AND r.player_id=b.player_id AND p_doc->>'visibility'='player' AND (p_doc->>'playerId')::uuid=r.player_id AND EXISTS(SELECT 1 FROM public.campaign_players p JOIN public.house_memberships m ON m.player_id=p.id WHERE p.id=b.player_id AND p.user_id=b.owner_user_id AND m.house_id=r.house_id AND m.can_edit))) THEN RETURN false; END IF; IF (p_doc->>'baseVersion')::integer<>r.version OR (p_doc->>'version')::integer<>r.version+1 THEN RETURN false; END IF; UPDATE public.campaign_records SET title=p_doc->>'title',content=p_doc->>'content',version=version+1,updated_by=b.confirmed_by,updated_at=now(),sync_state='pending' WHERE id=r.id; RETURN true; END $$; REVOKE ALL ON FUNCTION public.apply_drive_record(uuid,text,jsonb,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_drive_record(uuid,text,jsonb,integer) TO service_role;